const $=s=>document.querySelector(s), params=new URLSearchParams(location.search);
let direction=params.get('direction')||'compact',detail=params.get('detail')||'useful',theme=params.get('theme')||'light',page='',dirty=false,baseline='',toastTimer;
const drafts=new Map();
const names={home:'Settings',routine:'Evening motion',scene:'Evening glow',room:'Living room',rooms:'Rooms & groups',connection:'Sensor gateway',device:'Sofa lamp',devices:'Devices',logs:'Logs',attention:'Device attention',preferences:'Preferences','window-device':'Window light'};
const navGroups=[['',[['home','Overview','⌂','']]],['Home setup',[['rooms','Rooms & groups','▦','8'],['devices','Devices','◉','48']]],['Automation',[['scene','Scenes','◐','12'],['routine','Routines','⌘','16']]],['Connections',[['connection','Integrations','⇄','4']]],['System',[['preferences','Preferences','⚙','']]],['Troubleshooting',[['attention','Device attention','△','2'],['logs','Logs','≡','']]]];
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function input(label,value,type='text',extra=''){return `<label class="field"><span>${label}</span><input aria-label="${label}" type="${type}" value="${value}" ${extra}></label>`;}
function select(label,options){return `<label class="field"><span>${label}</span><select aria-label="${label}">${options.map(x=>`<option>${x}</option>`).join('')}</select></label>`;}
function head(title,description,actions='',eyebrow=''){return `<div class="pagehead"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${eyebrow&&title!=='Settings'?`<input class="title-input" aria-label="Name" value="${title}">`:title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function tech(text){return `<div class="technical">${text}</div>`;}
function ref(href,label){return `<a class="entity-link" href="#${href}" title="Open ${label}; your draft stays here">${label} <span aria-hidden="true">↗</span></a>`;}
function panel(title,body,action='',desc=''){return `<section class="panel"><div class="panelhead"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>${body}</section>`;}
function identity(name,id,toggle='Enabled'){return `<section class="panel identity"><div class="identity-key">${tech(id)}</div><label class="toggle"><input type="checkbox" checked>${toggle}</label></section>`;}
function destination(title,description,href,icon){return `<a class="destination" href="#${href}"><span class="desticon">${icon}</span><span><strong>${title}</strong><p>${description}</p></span><span class="arrow">↗</span></a>`;}
function home(){return head('Settings','Configure your home and review anything that needs attention.','','')+`<div class="overview"><div class="stat"><small>Devices</small><strong>48</strong><small>46 reporting · 2 need attention</small></div><div class="stat"><small>Rooms & groups</small><strong>8</strong><small>Across 2 floorplans</small></div><div class="stat"><small>Scenes</small><strong>12</strong><small>Target states and transitions</small></div><div class="stat"><small>Routines</small><strong>16</strong><small>14 enabled · 2 paused</small></div></div>${attentionPanel()}<div class="landing-grid">${panel('Home setup',destination('Rooms & groups','8 groups · organize devices and linked groups','rooms','▦')+destination('Devices','48 devices · names, capabilities and reports','devices','◉')+`<div class="destination"><span class="desticon">⌂</span><span><strong>Floorplans</strong><p>2 floors · spatial device placement</p></span><span class="tag">Next study</span></div>`)}${panel('Automation',destination('Scenes','12 scenes · target states and transitions','scene','◐')+destination('Routines','16 routines · events, conditions and actions','routine','⌘')+`<div class="destination"><span class="desticon">ƒ</span><span><strong>Helpers & computed sources</strong><p>Values, modes and adaptive lighting</p></span><span class="tag">Next study</span></div>`)}</div><div class="landing-grid">${panel('Connections',destination('Integrations','4 connections · protocols and discovery','connection','⇄')+`<div class="destination"><span class="desticon">⋮</span><span><strong>Sensor & widget sources</strong><p>Measurements and dashboard data</p></span><span class="tag">Next study</span></div>`)}${panel('System & troubleshooting',destination('Logs','Recent messages, searchable at a glance','logs','≡')+`<div class="destination"><span class="desticon">⚙</span><span><strong>Preferences, assistant & backups</strong><p>System behavior and recovery</p></span><span class="tag">Next study</span></div>`)}</div>`;}
function triggerNode(second=false){return `<div class="node ${second?'':'linked'}"><div class="nodehead"><span class="nodeicon">${second?'◷':'◉'}</span>${second?'At a scheduled time':'When motion starts'}<span class="tag">${second?'02':'01'}</span></div><div class="fields">${second?input('Time','18:30','time'):select('Device',['Hall motion sensor','Living room motion sensor'])}${second?select('Repeat',['Every day','Weekdays','Weekends']):select('Event',['Motion becomes detected','Motion is reported'])}</div>${tech(second?'Europe/Helsinki · 0 30 18 * * *':'predicate_transition · /occupancy')}${!second?'<p class="hint">Live: no motion · 12 seconds ago</p>':''}</div>`;}
function conditionNode(){return `<div class="node linked"><div class="nodehead"><span class="nodeicon">⋔</span>Only if <span class="tag">ALL</span></div><div class="fields">${select('Match',['All conditions','Any condition'])}${select('Measurement',['Hall sensor · Illuminance','Living room · Illuminance'])}${select('Comparison',['Is below','Is above','Equals'])}${input('Threshold · lx','30','number')}</div>${tech('/illuminance &lt; 30')}<p class="hint">Current value <strong>18 lx</strong> · 12 seconds ago</p><button class="subtle" data-add="condition">+ Add condition</button></div>`;}
function actionNode(){return `<div class="node"><div class="nodehead"><span class="nodeicon">◐</span>Activate a scene <span class="tag">01</span></div><div class="fields">${select('Scene',['Evening glow','Bright','Night light'])}<div class="field wide"><span>Targets</span><div class="chips"><span class="chip">Living room<button aria-label="Remove Living room" data-remove-chip>×</button></span><span class="chip">Hallway<button aria-label="Remove Hallway" data-remove-chip>×</button></span></div><button class="subtle" data-add="target">+ Add room or device</button></div>${select('Transition',['Use scene transition','Override transition','Immediate'])}</div><div class="node-ref">${ref('scene','Open Evening glow')}</div><div class="node-scene-preview">${lightPreview({brightness:35})}${lightPreview({brightness:20,color:'2400 K'})}<span>Saved scene targets<br><small>2400–2700 K · 20–55%</small></span></div>${tech('activate_scene · 2 group targets')}</div>`;}
function routine(){return head('Evening motion','Turn on a gentle light when the home is dark.',`<button data-preview>▷ Preview draft</button>`,'ROUTINE')+identity('Evening motion','evening_motion')+`<div class="flow-tabs"><span class="selected">Flow</span><button class="subtle" data-demo="Activity will show recorded attempts and their actual evidence.">Activity ↗</button><button class="subtle" data-demo="Advanced definition editing will preserve stable node IDs and unknown fields.">Definition</button></div><section class="flow-board"><div class="flow-header"><span>Any starting event → check conditions → run actions in order</span><span class="tag">Auto layout</span></div><div class="flow-columns"><div><div class="lane-title"><span>WHEN</span><small>Either event</small></div>${triggerNode()}<div class="connector">OR</div>${triggerNode(true)}<button class="add-node" data-add="trigger">+ Add starting event</button></div><div><div class="lane-title"><span>ONLY IF</span><small>Must pass</small></div>${conditionNode()}</div><div><div class="lane-title"><span>THEN</span><small>In order</small></div>${actionNode()}<button class="add-node" data-add="branch">+ Add action or branch</button></div></div></section><div class="flow-note"><span><span class="status-dot"></span><strong>Last recorded run · 18:42</strong><br>Conditions passed; scene command dispatched.</span><span>Current readings describe now.<br>They do not explain an earlier run.</span></div><div id="preview"></div><details><summary>Execution settings <span class="tag">Defaults</span></summary><div class="fields">${select('While already running',['Use saved execution policy','Show policy choices'])}${input('Routine ID','evening_motion')}</div></details>`;}
function scene(){const row=(name,kind,level,temp,key)=>`<tr><td class="targetname"><strong>${name==='Hallway'?name:ref(kind==='Room'?'room':'device',name)}</strong><small>${kind}</small>${tech(key)}</td><td data-label="Power"><select aria-label="${name} power"><option>On</option><option>Off</option><option>Keep current</option></select></td><td data-label="Brightness"><div class="range-value"><input aria-label="${name} brightness" type="range" min="0" max="100" value="${level}"><output>${level}%</output></div></td><td data-label="Color"><span class="swatch"></span><select aria-label="${name} color"><option>${temp} K</option><option>Color…</option><option>Keep current</option></select></td><td data-label="Transition"><input aria-label="${name} transition seconds" type="number" value="2" min="0" step="0.1" style="width:65px"> <small style="display:inline">s</small></td><td><button class="row-button" data-remove-row aria-label="Remove ${name}">×</button></td></tr>`;return head('Evening glow','A warm, low light for the end of the day.',`<button data-demo="Demo only: Activate saved scene would send a live command independently of your draft.">▷ Activate saved scene</button>`,'SCENE')+identity('Evening glow','evening_glow','Show in home')+panel('Room & group targets',`<div class="tablewrap scene-table"><table><thead><tr><th>Target</th><th>Power</th><th>Brightness</th><th>Color</th><th>Transition</th><th></th></tr></thead><tbody>${row('Living room','Room',35,2700,'group: living_room')}${row('Hallway','Room',20,2400,'group: hallway')}</tbody></table></div><p class="hint">Groups apply in saved order. A later group wins when memberships overlap.</p>`,`<button data-demo="The production picker will support selecting multiple rooms and groups.">+ Add groups</button>`)+panel('Device overrides',`<div class="tablewrap scene-table"><table><thead><tr><th>Target</th><th>Power</th><th>Brightness</th><th>Color</th><th>Transition</th><th></th></tr></thead><tbody>${row('Sofa lamp','Device override',55,2700,'mqtt_home/sofa_lamp')}</tbody></table></div><p class="hint">Device targets take precedence over the group targets above.</p>`,`<button data-demo="The production picker will support selecting multiple devices.">+ Add devices</button>`)+`<div class="two-col">${panel('Used by',`<div class="subsection">${ref('routine','Evening motion')}<small>Activate scene</small></div>`)}${panel('Target modes',`<p class="hint" style="margin:0">These rows set explicit values. A target may also follow a device or another scene.</p><button class="subtle" data-demo="The next scene concept will show link mode and target scopes.">Explore link modes →</button>`)}</div><details><summary>Advanced · script and technical definition</summary><p class="hint">Full script authoring and raw configuration are part of the implementation plan.</p></details>`;}
function rooms(){return head('Rooms & groups','Organize physical spaces and collections of devices.',`<button data-demo="Creation concept: name, optional members, and one explicit Create action.">+ Add room or group</button>`)+`<div class="toolbar"><input placeholder="Find a room or group…" aria-label="Search groups" data-filter><span class="tag">8 groups</span></div>`+panel('Your spaces',`<div class="tablewrap"><table><thead><tr><th>Name</th><th>Direct members</th><th>Linked groups</th><th>Visibility</th></tr></thead><tbody>${[['Living room',6,1],['Hallway',3,0],['Kitchen',8,0],['Bedroom',5,0],['Office',7,0],['Downstairs',0,3],['Upstairs',0,2],['All lights',0,5]].map(([name,n,linked])=>`<tr data-search="${name.toLowerCase()}"><td><strong>${name==='Living room'?ref('room',name):name}</strong></td><td>${n} devices</td><td>${linked||'—'}</td><td><span class="tag">${name==='All lights'?'Hidden':'Visible'}</span></td></tr>`).join('')}</tbody></table></div>`,'','Open Living room to try the detail concept.');}
function room(){return head('Living room','6 direct devices · 1 linked group · 8 resolved members','','ROOMS & GROUPS')+identity('Living room','living_room','Show in home')+`<div class="room-grid"><div>${panel('Direct members',`<div id="members">${['Sofa lamp','Ceiling light','Window light','Bookshelf lamp','Room sensor','Wall switch'].map((name,i)=>`<div class="member"><span class="device-icon">${i<4?lightPreview({brightness:[55,35,20,35][i],color:i===2?'2400 K':'2700 K'},'Requested state'):'▣'}</span><span><strong>${i===0?ref('device',name):name}</strong><small>${i<4?'Light':'Sensor'} · ${ref('connection','Sensor gateway')}</small></span><button class="row-button" data-remove-row aria-label="Remove ${name}">×</button></div>`).join('')}</div>`,`<button data-add="member">+ Add devices</button>`)}${panel('Linked groups',`<div class="member"><span class="device-icon">▦</span><span><strong>Reading corner</strong><small>2 additional devices · inherited membership</small></span><button class="row-button" data-remove-row aria-label="Remove linked group">×</button></div>`,`<button data-demo="Searchable multi-select for linked groups; cyclic links will be rejected.">+ Link groups</button>`)}</div><div>${panel('Placement',`<small>Ground floor · Living room</small><div class="floorplan" aria-label="Illustrative floorplan"><div class="current">Living room</div><div>Kitchen</div><div>Hallway</div></div><p class="hint">A compact spatial reference. Editing opens the floorplan workspace.</p>`)}${panel('Related configuration',`<div class="subsection">${ref('scene','Evening glow')}<small>Scene</small></div><div class="subsection">${ref('routine','Evening motion')}<small>Routine</small></div>`)}</div></div>`;}
function connection(){return head('Sensor gateway','Generic MQTT · enabled · device reports available','','INTEGRATION')+`<div class="two-col"><div>${panel('Connection',`<div class="fields">${input('Host','mqtt.home.local')}${input('Port','1883','number')}${select('Profile',['Generic MQTT','Zigbee2MQTT','ESPHome'])}${input('Topic','home/devices/+/state')}${input('Username','homectl')}${input('Password','','password','placeholder="Stored · leave unchanged"')}</div>`)}${panel('Sensor value fields',`<p class="hint" style="margin:0 0 16px">Keep each value you want to use from an incoming report.</p><div id="sensor-paths"><div class="repeat-row"><input aria-label="Sensor field 1" value="/temperature"><button data-remove-row aria-label="Remove temperature field">×</button></div><div class="repeat-row"><input aria-label="Sensor field 2" value="/humidity"><button data-remove-row aria-label="Remove humidity field">×</button></div><div class="repeat-row"><input aria-label="Sensor field 3" value="/occupancy"><button data-remove-row aria-label="Remove occupancy field">×</button></div></div><button class="subtle" data-add="path">+ Add field</button>${tech('sensor_value_fields[] · JSON pointers')}`)}${panel('Device attention',reportingFields('integration'))}<details><summary>Advanced · payload mapping and delivery policy</summary><div class="fields">${input('Device ID field','/id')}${input('Minimum update interval · ms','0','number')}</div></details></div><div>${panel('Devices from this connection',`<div class="metric"><span>Discovered</span><strong>12 devices</strong></div><div class="metric"><span>Recent reports</span><strong>11 devices</strong></div><div class="subsection">${ref('device','Sofa lamp')}<span class="tag green">Reporting</span></div><div class="subsection">${ref('devices','View all devices')}<small>↗</small></div><p class="hint">Device reports are evidence of activity. Enabled alone does not confirm gateway connectivity.</p>`)}${panel('Technical identity',`${tech('integration_id: mqtt_home')}<div class="metric"><span>Plugin</span><strong>mqtt</strong></div><div class="metric"><span>Configuration</span><strong>Database</strong></div>`)}</div></div>`;}
function devices(){return head('Devices','See where each device belongs and what it last reported.',`<button data-demo="Devices are discovered through integrations; manual options depend on the plugin.">Manage discovery</button>`)+`<div class="toolbar"><input aria-label="Search devices" placeholder="Find a device by name…" data-filter><span class="tag">48 devices · 2 need attention</span></div>`+panel('Device catalog',`<div class="tablewrap"><table><thead><tr><th>Device</th><th>Group</th><th>Connection</th><th>Latest evidence</th></tr></thead><tbody>${['Sofa lamp','Ceiling light','Hall motion sensor','Kitchen strip','Bedroom lamp','Office sensor','Window light','Old reading lamp'].map((n,i)=>`<tr data-search="${n.toLowerCase()}"><td><strong>${i===0?ref('device',n):n}</strong>${tech('mqtt_home/'+n.toLowerCase().replaceAll(' ','_'))}</td><td>${i<2?ref('room','Living room'):'Other groups'}</td><td>${ref('connection','Sensor gateway')}</td><td><span class="tag ${i>5?'amber':'green'}">${i===7?'Missing saved reference':i===6?'Last report · 2 h ago':'Reported · 12 s ago'}</span></td></tr>`).join('')}</tbody></table></div>`,'','Open Sofa lamp to try the detail concept.');}
function device(){return head('Sofa lamp','Light · Living room · Sensor gateway','','DEVICE')+`<div class="two-col"><div>${panel('Configuration',`<div class="fields">${input('Display name','Sofa lamp')}${select('Management',['Managed by homectl','Unmanaged'])}</div>${tech('mqtt_home/sofa_lamp')}<div class="subsection"><span>Member of</span>${ref('room','Living room')}</div><div class="subsection"><span>Connection</span>${ref('connection','Sensor gateway')}</div>`)}${panel('Live controls',`<div class="device-hero"><div class="device-orb">${lightPreview({brightness:55},'Requested state')}</div><div><h3>Requested on · 55%</h3><p class="hint">Latest report matches · 12 seconds ago</p></div></div><div class="fields">${select('Power',['On','Off'])}${input('Brightness · %','55','number')}</div><button class="primary" style="margin-top:16px" data-live>Send command</button><p class="hint">This command affects the device immediately. It is separate from saving its configuration.</p>`)}${panel('Reporting',reportingFields('device'))}${panel('Calibration',`<div class="subsection"><span>Color profile</span><span>Device default</span></div><button class="subtle" data-demo="Calibration uses a dedicated preview/session workflow.">Open calibration workspace ↗</button>`)}</div><div>${panel('Requested & reported',`<div class="metric"><span>Requested</span><strong class="state-value">${lightPreview({brightness:55},'Requested state')} On · 55% · 2700 K</strong></div><div class="metric"><span>Latest report</span><strong class="state-value">${lightPreview({brightness:55},'Latest report')} On · 55% · 2700 K</strong></div><div class="metric"><span>Report type</span><strong>Fresh, not retained</strong></div><div class="metric"><span>Reported availability</span><strong>Online</strong></div><p class="hint">A device report is the available evidence; it is not independent physical verification.</p>`)}${panel('Related configuration',`<div class="subsection">${ref('scene','Evening glow')}<small>Explicit target</small></div><div class="subsection">${ref('routine','Evening motion')}<small>Via scene</small></div>`)}</div></div>`;}
function logs(){const messages=[['INFO','automation','Routine evening_motion: condition passed; dispatching 1 action'],['INFO','scene_commands','Scene evening_glow activation accepted for 8 devices'],['INFO','integrations::mqtt','Device sofa_lamp reported requested state'],['WARN','device_health','Window light has not reported since 16:42:05; expected within 30 min'],['INFO','automation','Routine hallway_off: timer replaced; next event in 120 s'],['DEBUG','state','Published device patch revision 8421'],['INFO','integrations::mqtt','Hall sensor: occupancy=true, illuminance=18'],['INFO','device_health','Office sensor is reporting again; missing-report warning cleared'],['DEBUG','automation','Condition hallway_dark evaluated false'],['INFO','sources','Computed circadian output: 2700 K, brightness 0.35'],['INFO','automation','Routine evening_motion: run completed'],['DEBUG','integrations::mqtt','Received report for kitchen_strip'],['INFO','scene_commands','Scene bright activation accepted for office'],['INFO','state','Client requested full-state resync'],['DEBUG','state','Published device patch revision 8420'],['INFO','integrations::mqtt','Bedroom lamp reported requested state'],['INFO','config','Updated scene evening_glow; persisted to database'],['INFO','automation','Routine morning_light: schedule armed'],['DEBUG','sources','Source daylight refreshed'],['INFO','integrations::mqtt','Room sensor: temperature=21.4, humidity=43']];return head('Logs','Recent server messages. Filter, scan, and open the full message.',`<button data-demo="Refresh paused in this static demo; production will freeze the displayed buffer.">Ⅱ Pause refresh</button>`)+`<div class="toolbar"><input data-log-search placeholder="Search messages or sources…" aria-label="Search logs"><select aria-label="Filter log level" data-log-level><option>All levels</option><option>INFO</option><option>WARN</option><option>DEBUG</option></select><span class="right tag">Newest first</span></div><section class="panel logpanel"><table class="logs"><thead><tr><th>Time</th><th>Level</th><th class="logsource">Source</th><th>Message</th></tr></thead><tbody>${messages.map(([level,source,msg],i)=>`<tr class="${level==='WARN'?'warning':''}" data-level="${level}" data-search="${(source+' '+msg).toLowerCase()}"><td class="logtime">18:42:${String(59-i).padStart(2,'0')}</td><td class="loglevel">${level}</td><td class="logsource">${source}</td><td><button data-expand-log aria-expanded="false">${msg}</button></td></tr>`).join('')}</tbody></table></section><div class="logfoot"><span>20 illustrative entries · server retains the latest 500</span><span>Times in Europe/Helsinki · select a message to expand</span></div>`;}
const renderers={home,routine,scene:sceneRefined,room,rooms,connection,device,devices,logs,attention:attentionPage,preferences:preferencesPage,'window-device':windowDevicePage};
function serialize(){const root=$('#main').cloneNode(true),a=$('#main').querySelectorAll('input,select'),b=root.querySelectorAll('input,select');a.forEach((el,i)=>{if(el.tagName==='SELECT')b[i].querySelectorAll('option').forEach((o,j)=>o.toggleAttribute('selected',j===el.selectedIndex));else{b[i].setAttribute('value',el.value);b[i].toggleAttribute('checked',el.checked);}});root.querySelectorAll('.item-menu').forEach(el=>el.removeAttribute('open'));return root.innerHTML;}
function setDirty(){decorateRemovalButtons();dirty=serialize()!==baseline;$('#savebar').hidden=!dirty;$('#save-context').textContent=`${names[page]} · demo draft only`;}
function render(){if(page)drafts.set(page,{html:serialize(),dirty,baseline});page=location.hash.slice(1)||'home';if(!renderers[page])page='home';const cached=drafts.get(page);$('#main').innerHTML=cached?.html||renderers[page]();decorateRemovalButtons();dirty=cached?.dirty||false;baseline=cached?.baseline||serialize();$('#savebar').hidden=!dirty;$('#save-context').textContent=`${names[page]} · demo draft only`;const category={routine:'Routines',scene:'Scenes',room:'Rooms & groups',connection:'Integrations',device:'Devices'}[page];$('#crumb').innerHTML=page==='home'?'<span>Your home</span>':`<a href="#home">Settings</a>${category?`<span>/</span><a href="#${page==='room'?'rooms':page==='device'?'devices':'home'}">${category}</a>`:''}`;$('#nav').innerHTML=navGroups.map(([group,items])=>`${group?`<div class="nav-group">${group}</div>`:''}${items.map(([id,label,icon,count])=>`<a href="#${id}" class="nav-item ${id===page||(page==='room'&&id==='rooms')||(page==='device'&&id==='devices')?'active':''}"><span class="nav-icon">${icon}</span>${label}${count?`<span class="nav-count">${count}</span>`:''}</a>`).join('')}`).join('');$('.sidebar').classList.remove('open');window.scrollTo(0,0);}
function updateStyle(){document.body.className=[direction==='soft'?'soft':'',detail==='minimal'?'minimal':'',theme==='dark'?'dark':''].join(' ');$('#direction').value=direction;$('#detail').value=detail;$('#theme').value=theme;history.replaceState(null,'',`?${new URLSearchParams({direction,detail,theme})}${location.hash}`);}
$('#direction').onchange=e=>{direction=e.target.value;updateStyle();};$('#detail').onchange=e=>{detail=e.target.value;updateStyle();};$('#theme').onchange=e=>{theme=e.target.value;updateStyle();};$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');
$('#main').addEventListener('input',e=>{if(e.target.matches('[data-log-search]')){filterLogs();return;}if(e.target.matches('[data-filter]')){const q=e.target.value.toLowerCase();$('#main').querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.includes(q));return;}if(e.target.closest('.panel')?.querySelector('[data-live]'))return;if(e.target.type==='range')e.target.nextElementSibling.value=e.target.value+'%';setDirty();});
$('#main').addEventListener('change',e=>{if(e.target.matches('[data-log-level]')){filterLogs();return;}if(e.target.closest('.panel')?.querySelector('[data-live]'))return;if(e.target.matches('input,select'))setDirty();});
function filterLogs(){const q=$('[data-log-search]').value.toLowerCase(),level=$('[data-log-level]').value;document.querySelectorAll('.logs tbody tr').forEach(el=>el.hidden=!(el.dataset.search.includes(q)&&(level==='All levels'||el.dataset.level===level)));}
document.addEventListener('click',e=>{const demo=e.target.closest('[data-demo]');if(demo){notify(demo.dataset.demo);return;}const remove=e.target.closest('[data-remove-row]');if(remove){remove.closest('tr,.member,.repeat-row').remove();setDirty();return;}if(e.target.closest('[data-remove-chip]')){e.target.closest('.chip').remove();setDirty();return;}const expand=e.target.closest('[data-expand-log]');if(expand){const on=expand.closest('tr').classList.toggle('expanded');expand.setAttribute('aria-expanded',on);return;}if(e.target.closest('[data-live]')){notify('Demo command only. No device was contacted.');return;}if(e.target.closest('[data-preview]')){$('#preview').innerHTML='<div class="preview-result"><strong>Illustrative draft preview</strong><br>Assuming the motion trigger fires: sample illuminance (18 lx) passes the threshold. The scene action would be planned. This static prototype does not evaluate edited values or contact the server.</div>';return;}const add=e.target.closest('[data-add]');if(add){const kind=add.dataset.add;if(kind==='path')$('#sensor-paths').insertAdjacentHTML('beforeend','<div class="repeat-row"><input aria-label="New sensor field" placeholder="/pressure"><button data-remove-row aria-label="Remove new field">×</button></div>');if(kind==='trigger')add.insertAdjacentHTML('beforebegin',`<div class="connector">OR</div>${triggerNode(true)}`);if(kind==='condition')add.insertAdjacentHTML('beforebegin',`<div class="fields" style="margin-top:12px">${select('Additional condition',['Home mode','Time of day'])}${select('Value',['Home','Away'])}</div>`);if(kind==='target')add.previousElementSibling.insertAdjacentHTML('beforeend','<span class="chip">Kitchen<button aria-label="Remove Kitchen" data-remove-chip>×</button></span>');if(kind==='branch')add.insertAdjacentHTML('beforebegin',`<div class="flow-branch"><div class="node"><div class="nodehead">Choose · first matching branch</div>${select('If home mode is',['Evening','Night'])}<div class="node-ref">Then ${ref('scene','Evening glow')}</div></div><p class="hint">Add or reorder branches inside this block.</p></div>`);if(kind==='member')$('#members').insertAdjacentHTML('beforeend','<div class="member"><span class="device-icon">◉</span><span><strong>Reading lamp</strong><small>Added to demo draft</small></span><button class="row-button" data-remove-row aria-label="Remove reading lamp">×</button></div>');setDirty();}});
$('#save').onclick=()=>{if(page==='preferences'){detail=$('[data-advanced-setting]').checked?'useful':'minimal';updateStyle();$('#preference-status').textContent='Saved for all settings pages · demo only';}baseline=serialize();dirty=false;$('#savebar').hidden=true;notify('Demo draft saved in this tab. No server configuration changed.');};$('#discard').onclick=()=>{$('#main').innerHTML=baseline;dirty=false;$('#savebar').hidden=true;notify('Draft discarded.');};window.addEventListener('hashchange',render);window.addEventListener('beforeunload',e=>{if(dirty||[...drafts.entries()].some(([key,x])=>key!==page&&x.dirty)){e.preventDefault();e.returnValue='';}});updateStyle();render();
